const fs = require('fs');
function bal(path){const rows=fs.readFileSync(path,'utf8').trim().split(/\r?\n/);const head=rows[0].split(',');const out={};let D=0,C=0;for(const r of rows.slice(1)){const p=r.split(',');const acct=p[0],d=parseFloat(p[p.length-2]||0)||0,c=parseFloat(p[p.length-1]||0)||0;out[acct]=(out[acct]||0)+d-c;D+=d;C+=c;}return {saldos:out,D,C,head};}
function raz(path){const rows=fs.readFileSync(path,'utf8').trim().split(/\r?\n/);const out={};let D=0,C=0;for(const r of rows.slice(1)){const p=r.split(',');const acct=p[0],d=parseFloat(p[p.length-2]||0)||0,c=parseFloat(p[p.length-1]||0)||0;out[acct]=(out[acct]||0)+d-c;D+=d;C+=c;}return {mov:out,D,C};}

const ab = bal('/work/workspace/documents/balancete_abertura.csv');
const b1 = bal('/work/workspace/documents/mes_01/balancete.csv');
const r1 = raz('/work/workspace/documents/mes_01/razao.csv');
const b2 = bal('/work/workspace/documents/mes_02/balancete.csv');
const r2 = raz('/work/workspace/documents/mes_02/razao.csv');
const b3 = bal('/work/workspace/documents/mes_03/balancete.csv');
const r3 = raz('/work/workspace/documents/mes_03/razao.csv');

const results = [];
// 1. squares
results.push(['jan balancete D=C', b1.D, b1.C, b1.D===b1.C]);
results.push(['jan razão D=C', r1.D, r1.C, r1.D===r1.C]);
results.push(['fev balancete D=C', b2.D, b2.C, b2.D===b2.C]);
results.push(['mar balancete D=C', b3.D, b3.C, b3.D===b3.C]);
// 2. articulations
function art(base, mov, target){let bad=0;const keys=new Set([...Object.keys(base.saldos),...Object.keys(mov.mov),...Object.keys(target.saldos)]);const diffs=[];for(const k of keys){const exp=(base.saldos[k]||0)+(mov.mov[k]||0);if(Math.abs(exp-(target.saldos[k]||0))>0.004){bad++;diffs.push([k,exp,target.saldos[k]||0]);}}return {bad,n:keys.size,diffs};}
results.push(['abertura+razjan = baljan', JSON.stringify(art(ab,r1,b1))]);
results.push(['baljan+razfev = balfev', JSON.stringify(art(b1,r2,b2))]);
results.push(['balfev+razmar = balmar', JSON.stringify(art(b2,r3,b3))]);
// 3. Jan numbers
const s=b1.saldos;
const ll1 = (s['7.1.01']||0) - ((s['7.1.02']||0)+(s['7.1.03']||0)+(s['4.1.01']||0)+(s['4.2.01']||0)+(s['4.2.02']||0)+(s['4.2.03']||0)+(s['4.2.04']||0)+(s['4.2.05']||0)+(s['5.1.01']||0));
results.push(['jan contas usadas', JSON.stringify(Object.fromEntries(Object.entries(s).filter(([k])=>k.startsWith('7')||k.startsWith('4')||k.startsWith('5'))))]);
results.push(['jan LL calculado', ll1, 139583, Math.abs(ll1-139583)<0.01]);
results.push(['jan PIS débito 234950 == 2.1.03 mov', (r1.mov['2.1.03']||0), -(234950+177800), (r1.mov['2.1.03']||0)]);
results.push(['jan 1.1.04 saldo', s['1.1.04'], 166167, Math.abs(s['1.1.04']-166167)<0.01]);
results.push(['jan a_recolher livros = 234950-166167', 234950-166167]);
results.push(['fev 1.1.04 saldo livros', b2.saldos['1.1.04'], 323676, Math.abs(b2.saldos['1.1.04']-323676)<0.01]);
results.push(['fev 4.2.04', b2.saldos['4.2.04'], 120000]);
results.push(['fev estoques', b2.saldos['1.1.03'], 4973200, Math.abs(b2.saldos['1.1.03']-4973200)<0.01]);
results.push(['fev caixa', b2.saldos['1.1.01'], 3094800, Math.abs(b2.saldos['1.1.01']-3094800)<0.01]);
results.push(['fev fornecedores', b2.saldos['2.1.01'], 3593676, Math.abs(b2.saldos['2.1.01']-3593676)<0.01]);
results.push(['fev 2.1.03', b2.saldos['2.1.03'], 1572000, Math.abs(b2.saldos['2.1.03']-1572000)<0.01]);
// Feb LL
const s2=b2.saldos;
const llYTD2 = s2['7.1.01'] - (s2['7.1.02']+s2['7.1.03']+s2['4.1.01']+s2['4.2.01']+s2['4.2.02']+s2['4.2.03']+s2['4.2.04']+s2['4.2.05']+s2['5.1.01']);
results.push(['fev LL YTD livros', llYTD2, 332666, Math.abs(llYTD2-332666)<0.01]);
// LALUR final
const LL=604149, AD=163000, antes=LL+AD, trava=Math.round(antes*0.30*100)/100, LR=antes-trava;
const irpj15=Math.round(LR*0.15*100)/100, exc=Math.max(0,LR-60000), ad=Math.round(exc*0.10*100)/100, csll=Math.round(LR*0.09*100)/100;
results.push(['trava', trava, 230144.70]);
results.push(['LR', LR, 537004.30]);
results.push(['IRPJ15', irpj15, 80550.65]);
results.push(['adicional', ad, 47700.43]);
results.push(['IRPJ total', irpj15+ad, 128251.08]);
results.push(['CSLL', csll, 48330.39]);
results.push(['total', irpj15+ad+csll, 176581.47]);
results.push(['ParteB', 900000-trava, 669855.30]);
// sensitivity B/C
function taxes(adi){const a=LL+adi;const t=Math.round(a*0.3*100)/100;const lr=a-t;const i15=lr*0.15;const ex=Math.max(0,lr-60000)*0.1;const cs=lr*0.09;return {antes:a,trava:t,lr:lr,exact:i15+ex+cs};}
results.push(['cenarioB', JSON.stringify(taxes(78000))]);
results.push(['cenarioC', JSON.stringify(taxes(248000))]);
// mes_02 projection checks (até fev): base ajustado 321566+adi
function proj(adi){const a=321566+adi;return {a, trava30:a*0.3};}
results.push(['mes02 A', JSON.stringify(proj(163000))]);
results.push(['mes02 B', JSON.stringify(proj(78000))]);
results.push(['mes02 C', JSON.stringify(proj(248000))]);
// post-trava base diff B->C (até fev)
const bB=399566*0.7, bC=569566*0.7;
results.push(['base pós-trava B,C,diff (até fev)', bB, bC, bC-bB]);
results.push(['Q1 total PIS/COFINS', 79883+81141+82399]);
return results.map(r=>JSON.stringify(r)).join('\n');

